/* ws_test.c - tests for wstring.c. Do not edit this file; add your own tests to
   my_tests.c instead.

   Build and run with `make test`. Each group tests one function. When a test fails, the
   line number points at the CHECK that failed. If the program crashes, the last PASS or
   FAIL printed tells you where it got to: fix that first, then run it again. */

#include <stdint.h>
#include <stdio.h>

#include "wstring.h"
#include "ws_check.h"

/* The number of characters before text's terminator. */
static size_t cstr_length(const wchar_t *text)
{
    size_t n = 0;
    while (text[n] != L'\0') {
        n++;
    }
    return n;
}

/* true if s is a WString whose length and bytes are exactly expected's. */
static bool reads(const WString *s, const wchar_t *expected)
{
    return s != NULL && ws_length(s) == cstr_length(expected) &&
           check_same_cstr(ws_cstr(s), expected);
}

/* true if s is a WString whose C string ends at its length, with nothing cut short. */
static bool terminated(const WString *s)
{
    return s != NULL && cstr_length(ws_cstr(s)) == ws_length(s);
}

static void test_ws_new(void)
{
    wchar_t buf[] = L"Dune";
    WString *dune = ws_new(L"Dune");
    WString *empty = ws_new(L"");
    WString *from_buf = ws_new(buf);

    check_group("ws_new");
    CHECK(dune != NULL, "ws_new(\"Dune\") returns a WString");
    CHECK(ws_length(dune) == 4, "ws_new(\"Dune\") has length 4");
    CHECK(reads(dune, L"Dune"), "ws_new(\"Dune\") reads back \"Dune\"");
    CHECK(terminated(dune), "ws_new(\"Dune\") keeps a terminator after its last byte");
    CHECK(empty != NULL, "ws_new(\"\") returns a WString");
    CHECK(reads(empty, L""), "ws_new(\"\") has length 0 and reads back \"\"");
    CHECK(terminated(empty), "ws_new(\"\") keeps a terminator");
    CHECK(ws_new(NULL) == NULL, "ws_new(NULL) returns NULL");

    buf[0] = L'J';
    CHECK(reads(from_buf, L"Dune"), "ws_new copies its text: changing the array afterwards "
                                    "leaves the WString alone");
    CHECK(from_buf != NULL && ws_cstr(from_buf) != buf,
          "ws_new's bytes are in memory of their own, not the caller's array");

    ws_free(dune);
    ws_free(empty);
    ws_free(from_buf);
}

static void test_ws_length_cstr_free(void)
{
    WString *long_one = ws_new(L"It is by will alone I set my mind in motion.");

    check_group("ws_length, ws_cstr and ws_free");
    CHECK(ws_length(long_one) == 44, "ws_length counts every byte of a longer WString");
    CHECK(ws_length(NULL) == 0, "ws_length(NULL) is 0");
    CHECK(check_same_cstr(ws_cstr(NULL), L""), "ws_cstr(NULL) is \"\"");
    ws_free(NULL);
    CHECK(true, "ws_free(NULL) returns without crashing");

    ws_free(long_one);
}

static void test_ws_at(void)
{
    WString *dune = ws_new(L"Dune");
    wchar_t c = L'#';

    check_group("ws_at");
    CHECK(ws_at(dune, 0, &c) && c == L'D', "ws_at(\"Dune\", 0) is 'D'");
    c = L'#';
    CHECK(ws_at(dune, 3, &c) && c == L'e', "ws_at(\"Dune\", 3) is 'e', the last byte");
    c = L'#';
    CHECK(!ws_at(dune, 4, &c), "ws_at(\"Dune\", 4) is out of range and returns false");
    CHECK(c == L'#', "ws_at out of range leaves *out alone");
    CHECK(!ws_at(dune, SIZE_MAX, &c) && c == L'#', "ws_at(\"Dune\", SIZE_MAX) returns false");
    CHECK(!ws_at(NULL, 0, &c) && c == L'#', "ws_at(NULL, 0) returns false");
    CHECK(!ws_at(dune, 0, NULL), "ws_at with a NULL out returns false");

    ws_free(dune);
}

static void test_ws_copy(void)
{
    WString *original = ws_new(L"Dune");
    WString *copy = ws_copy(original);
    WString *empty = ws_new(L"");
    WString *empty_copy = ws_copy(empty);

    check_group("ws_copy");
    CHECK(reads(copy, L"Dune"), "ws_copy of \"Dune\" reads \"Dune\"");
    CHECK(copy != NULL && copy != original, "ws_copy returns a new WString, not its argument");
    CHECK(copy != NULL && original != NULL && ws_cstr(copy) != ws_cstr(original),
          "ws_copy's bytes are in memory of their own");
    CHECK(reads(empty_copy, L""), "ws_copy of \"\" reads \"\"");
    CHECK(empty_copy != NULL && empty_copy != empty, "ws_copy of \"\" returns a new WString too");
    CHECK(ws_copy(NULL) == NULL, "ws_copy(NULL) returns NULL");

    ws_free(original);
    CHECK(reads(copy, L"Dune"), "the copy still reads \"Dune\" after the original is freed");

    if (copy != original) {
        ws_free(copy);
    }
    if (empty_copy != empty) {
        ws_free(empty_copy);
    }
    ws_free(empty);
}

static void test_ws_concat(void)
{
    WString *du = ws_new(L"Du");
    WString *ne = ws_new(L"ne");
    WString *empty = ws_new(L"");
    WString *dune = ws_concat(du, ne);
    WString *left_empty = ws_concat(empty, ne);
    WString *right_empty = ws_concat(du, empty);
    WString *both_empty = ws_concat(empty, empty);
    WString *twice = ws_concat(dune, dune);

    check_group("ws_concat");
    CHECK(reads(dune, L"Dune"), "ws_concat(\"Du\", \"ne\") is \"Dune\"");
    CHECK(terminated(dune), "ws_concat's result keeps a terminator");
    CHECK(reads(left_empty, L"ne"), "ws_concat(\"\", \"ne\") is \"ne\"");
    CHECK(reads(right_empty, L"Du"), "ws_concat(\"Du\", \"\") is \"Du\"");
    CHECK(reads(both_empty, L""), "ws_concat(\"\", \"\") is \"\"");
    CHECK(reads(twice, L"DuneDune"), "ws_concat(s, s) is s twice");
    CHECK(reads(du, L"Du") && reads(ne, L"ne"), "ws_concat leaves both inputs unchanged");
    CHECK(ws_concat(NULL, ne) == NULL, "ws_concat(NULL, b) returns NULL");
    CHECK(ws_concat(du, NULL) == NULL, "ws_concat(a, NULL) returns NULL");

    ws_free(du);
    ws_free(ne);
    ws_free(empty);
    ws_free(dune);
    ws_free(left_empty);
    ws_free(right_empty);
    ws_free(both_empty);
    ws_free(twice);
}

static void test_ws_substring(void)
{
    WString *dune = ws_new(L"Dune");
    WString *middle = ws_substring(dune, 1, 2);
    WString *whole = ws_substring(dune, 0, 4);
    WString *at_end = ws_substring(dune, 4, 0);
    WString *at_start = ws_substring(dune, 0, 0);

    check_group("ws_substring");
    CHECK(reads(middle, L"un"), "ws_substring(\"Dune\", 1, 2) is \"un\"");
    CHECK(terminated(middle), "ws_substring's result keeps a terminator");
    CHECK(reads(whole, L"Dune"), "ws_substring(\"Dune\", 0, 4) is the whole WString");
    CHECK(reads(at_end, L""), "ws_substring(\"Dune\", 4, 0) is \"\": an empty range at the end");
    CHECK(reads(at_start, L""), "ws_substring(\"Dune\", 0, 0) is \"\"");
    CHECK(reads(dune, L"Dune"), "ws_substring leaves its input unchanged");
    CHECK(ws_substring(NULL, 0, 0) == NULL, "ws_substring(NULL, 0, 0) returns NULL");
    CHECK(ws_substring(dune, 5, 0) == NULL, "ws_substring(\"Dune\", 5, 0) starts past the "
                                            "end and returns NULL");
    CHECK(ws_substring(dune, 2, 3) == NULL, "ws_substring(\"Dune\", 2, 3) runs past the end "
                                            "and returns NULL");
    /* The last three are the overflow trap. If the program crashes here, look at how your
     range check adds start and len. */
    CHECK(ws_substring(dune, SIZE_MAX, 1) == NULL,
          "ws_substring(\"Dune\", SIZE_MAX, 1) returns NULL");
    CHECK(ws_substring(dune, 1, SIZE_MAX) == NULL,
          "ws_substring(\"Dune\", 1, SIZE_MAX) returns NULL");
    CHECK(ws_substring(dune, 2, SIZE_MAX - 1) == NULL,
          "ws_substring(\"Dune\", 2, SIZE_MAX - 1) returns NULL");

    ws_free(dune);
    ws_free(middle);
    ws_free(whole);
    ws_free(at_end);
    ws_free(at_start);
}

static void test_ws_to_upper(void)
{
    WString *dune = ws_new(L"Dune 2!");
    WString *upper = ws_to_upper(dune);
    WString *edges = ws_new(L"`az{@AZ[");
    WString *edges_upper = ws_to_upper(edges);
    WString *empty = ws_new(L"");
    WString *empty_upper = ws_to_upper(empty);
    WString *high = ws_new(L"\xe9"); /* a byte above 127, as in the UTF-8 for an accent */
    WString *high_upper = ws_to_upper(high);

    check_group("ws_to_upper");
    CHECK(reads(upper, L"DUNE 2!"), "ws_to_upper(\"Dune 2!\") is \"DUNE 2!\"");
    CHECK(reads(dune, L"Dune 2!"), "ws_to_upper leaves its input unchanged");
    CHECK(upper != NULL && upper != dune, "ws_to_upper returns a new WString");
    CHECK(reads(edges_upper, L"`AZ{@AZ["),
          "ws_to_upper changes 'a' and 'z' but not the bytes either side of them");
    CHECK(reads(empty_upper, L""), "ws_to_upper(\"\") is \"\"");
    CHECK(empty_upper != NULL && empty_upper != empty,
          "ws_to_upper(\"\") returns a new WString too");
    CHECK(reads(high_upper, L"\xe9"), "ws_to_upper keeps a byte above 127 as it is");
    CHECK(ws_to_upper(NULL) == NULL, "ws_to_upper(NULL) returns NULL");

    ws_free(dune);
    if (upper != dune) {
        ws_free(upper);
    }
    ws_free(edges);
    if (edges_upper != edges) {
        ws_free(edges_upper);
    }
    ws_free(empty);
    if (empty_upper != empty) {
        ws_free(empty_upper);
    }
    ws_free(high);
    if (high_upper != high) {
        ws_free(high_upper);
    }
}

static void test_ws_equals(void)
{
    WString *dune = ws_new(L"Dune");
    WString *dune2 = ws_new(L"Dune");
    WString *dun = ws_new(L"Dun");
    WString *june = ws_new(L"June");
    WString *dunk = ws_new(L"Dunk");
    WString *empty = ws_new(L"");
    WString *empty2 = ws_new(L"");

    check_group("ws_equals");
    CHECK(ws_equals(dune, dune2), "two separate \"Dune\"s are equal");
    CHECK(ws_equals(dune, dune), "a WString equals itself");
    CHECK(!ws_equals(dune, dun), "\"Dune\" and \"Dun\" are not equal (different lengths)");
    CHECK(!ws_equals(dun, dune), "\"Dun\" and \"Dune\" are not equal (different lengths)");
    CHECK(!ws_equals(dune, june), "\"Dune\" and \"June\" are not equal (first byte differs)");
    CHECK(!ws_equals(dune, dunk), "\"Dune\" and \"Dunk\" are not equal (last byte differs)");
    CHECK(ws_equals(empty, empty2), "\"\" equals \"\"");
    CHECK(!ws_equals(empty, dune), "\"\" and \"Dune\" are not equal");
    CHECK(ws_equals(NULL, NULL), "NULL equals NULL");
    CHECK(!ws_equals(NULL, dune), "NULL does not equal a WString");
    CHECK(!ws_equals(dune, NULL), "a WString does not equal NULL");
    CHECK(!ws_equals(NULL, empty), "NULL does not equal \"\"");

    ws_free(dune);
    ws_free(dune2);
    ws_free(dun);
    ws_free(june);
    ws_free(dunk);
    ws_free(empty);
    ws_free(empty2);
}

static void test_ws_compare(void)
{
    WString *dune = ws_new(L"Dune");
    WString *dune2 = ws_new(L"Dune");
    WString *dun = ws_new(L"Dun");
    WString *dunk = ws_new(L"Dunk");
    WString *a = ws_new(L"a");
    WString *b = ws_new(L"b");
    WString *aa = ws_new(L"aa");
    WString *empty = ws_new(L"");
    WString *high = ws_new(L"\xe9"); /* a byte above 127, as in the UTF-8 for an accent */

    check_group("ws_compare");
    CHECK(ws_compare(dune, dune2) == 0, "\"Dune\" compares equal to \"Dune\"");
    CHECK(ws_compare(a, b) < 0, "\"a\" sorts before \"b\"");
    CHECK(ws_compare(b, a) > 0, "\"b\" sorts after \"a\"");
    CHECK(ws_compare(dun, dune) < 0, "\"Dun\" sorts before \"Dune\" (a prefix comes first)");
    CHECK(ws_compare(dune, dun) > 0, "\"Dune\" sorts after \"Dun\"");
    CHECK(ws_compare(dune, dunk) < 0, "\"Dune\" sorts before \"Dunk\" (the last byte decides)");
    CHECK(ws_compare(dunk, dune) > 0, "\"Dunk\" sorts after \"Dune\"");
    CHECK(ws_compare(b, aa) > 0,
          "\"b\" sorts after the longer \"aa\" (bytes decide before length does)");
    CHECK(ws_compare(empty, a) < 0, "\"\" sorts before \"a\"");
    CHECK(ws_compare(high, a) > 0,
          "a byte above 127 sorts after 'a' (bytes compare as unsigned char)");
    CHECK(ws_compare(NULL, empty) < 0, "NULL sorts before \"\"");
    CHECK(ws_compare(empty, NULL) > 0, "\"\" sorts after NULL");
    CHECK(ws_compare(NULL, NULL) == 0, "NULL compares equal to NULL");

    ws_free(dune);
    ws_free(dune2);
    ws_free(dun);
    ws_free(dunk);
    ws_free(a);
    ws_free(b);
    ws_free(aa);
    ws_free(empty);
    ws_free(high);
}

static void test_ws_starts_with(void)
{
    WString *dune = ws_new(L"Dune");
    WString *du = ws_new(L"Du");
    WString *dx = ws_new(L"Dx");
    WString *une = ws_new(L"une");
    WString *dunes = ws_new(L"Dunes");
    WString *empty = ws_new(L"");

    check_group("ws_starts_with");
    CHECK(ws_starts_with(dune, du), "\"Dune\" starts with \"Du\"");
    CHECK(ws_starts_with(dune, dune), "\"Dune\" starts with \"Dune\"");
    CHECK(ws_starts_with(dune, empty), "\"Dune\" starts with \"\"");
    CHECK(ws_starts_with(empty, empty), "\"\" starts with \"\"");
    CHECK(!ws_starts_with(dune, dx), "\"Dune\" does not start with \"Dx\"");
    CHECK(!ws_starts_with(dune, une), "\"Dune\" does not start with \"une\"");
    CHECK(!ws_starts_with(dune, dunes), "\"Dune\" does not start with the longer \"Dunes\"");
    CHECK(!ws_starts_with(du, dune), "\"Du\" does not start with \"Dune\"");
    CHECK(!ws_starts_with(NULL, empty), "ws_starts_with(NULL, \"\") is false");
    CHECK(!ws_starts_with(dune, NULL), "ws_starts_with(\"Dune\", NULL) is false");
    CHECK(!ws_starts_with(NULL, NULL), "ws_starts_with(NULL, NULL) is false");

    ws_free(dune);
    ws_free(du);
    ws_free(dx);
    ws_free(une);
    ws_free(dunes);
    ws_free(empty);
}

static void test_ws_find(void)
{
    WString *dune = ws_new(L"Dune");
    WString *du = ws_new(L"Du");
    WString *ne = ws_new(L"ne");
    WString *e = ws_new(L"e");
    WString *x = ws_new(L"x");
    WString *dunes = ws_new(L"Dunes");
    WString *empty = ws_new(L"");
    WString *aaab = ws_new(L"aaab");
    WString *aab = ws_new(L"aab");
    WString *banana = ws_new(L"banana");
    WString *an = ws_new(L"an");
    size_t at = 99;

    check_group("ws_find");
    CHECK(ws_find(dune, du, &at) && at == 0, "\"Du\" is found in \"Dune\" at 0");
    at = 99;
    CHECK(ws_find(dune, ne, &at) && at == 2, "\"ne\" is found in \"Dune\" at 2");
    at = 99;
    CHECK(ws_find(dune, e, &at) && at == 3, "\"e\" is found in \"Dune\" at 3, the last byte");
    at = 99;
    CHECK(ws_find(dune, dune, &at) && at == 0, "\"Dune\" is found in \"Dune\" at 0");
    at = 99;
    CHECK(ws_find(dune, empty, &at) && at == 0, "\"\" is found in \"Dune\" at 0");
    at = 99;
    CHECK(ws_find(empty, empty, &at) && at == 0, "\"\" is found in \"\" at 0");
    at = 99;
    CHECK(ws_find(banana, an, &at) && at == 1, "\"an\" is found in \"banana\" at 1, the first "
                                               "of two");
    at = 99;
    CHECK(ws_find(aaab, aab, &at) && at == 1,
          "\"aab\" is found in \"aaab\" at 1 (after a partial match at 0)");
    at = 99;
    CHECK(!ws_find(dune, x, &at), "\"x\" is not found in \"Dune\"");
    CHECK(at == 99, "a failed ws_find leaves *index alone");
    CHECK(!ws_find(dune, dunes, &at), "the longer \"Dunes\" is not found in \"Dune\"");
    CHECK(!ws_find(empty, e, &at), "\"e\" is not found in \"\"");
    CHECK(!ws_find(NULL, empty, &at), "ws_find in NULL is false");
    CHECK(!ws_find(dune, NULL, &at), "ws_find of a NULL needle is false");
    CHECK(!ws_find(dune, du, NULL), "ws_find with a NULL index is false");
    CHECK(at == 99, "ws_find with a NULL argument leaves *index alone");

    ws_free(dune);
    ws_free(du);
    ws_free(ne);
    ws_free(e);
    ws_free(x);
    ws_free(dunes);
    ws_free(empty);
    ws_free(aaab);
    ws_free(aab);
    ws_free(banana);
    ws_free(an);
}

int main(void)
{
    test_ws_new();
    test_ws_length_cstr_free();
    test_ws_at();
    test_ws_equals();
    test_ws_compare();
    test_ws_starts_with();
    test_ws_find();
    test_ws_copy();
    test_ws_concat();
    test_ws_substring();
    test_ws_to_upper();
    return check_summary();
}
